# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import label_spans

class LabelTests(unittest.TestCase):
    def test_snaps_both_ends(self):
        labels = label_spans([Span(542, 1033)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = label_spans([Span(570, 660)], 60)
        self.assertEqual(labels, ["10:00-11:00 (1h 0m)"])

    def test_one_label_per_span_in_order(self):
        spans = [Span(540, 600), Span(780, 840)]
        self.assertEqual(
            label_spans(spans, 30),
            ["09:00-10:00 (1h 0m)", "13:00-14:00 (1h 0m)"]
        )

    def test_empty(self):
        self.assertEqual(label_spans([], 15), [])

    def test_collapsed_span_gets_zero_length(self):
        labels = label_spans([Span(542, 546)], 15)
        self.assertEqual(labels, ["09:00-09:00 (0h 0m)"])

    def test_bad_step(self):
        for step in (0, -15, 7, 25, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_spans([Span(540, 600)], step)
